// Renders as inline styles only, no <style> block, no <script>, no data-* attributes -
// a sanitizer strips markup after any of those and the table goes blank.
// class="zt-data" is required for Zingtree to capture the selection - it's not styling.
// Option values are action ids; dedupe by id, not name, since two actions can share a
// display name but carry different buckets.

let customer_action_pnrs = transforms.customer_action_pnrs || [];

const INK = "#101820";
const MUTED = "#667085";
const LINE = "#e7eaee";
const BG = "#f6f4ef";
const CARD = "#ffffff";
const BLUE = "#163a5f";
const SKY = "#d8ecf5";
const SAND = "#f3eadb";
const GREEN = "#dce8df";

const S = {
  board: "font-family:Arial,sans-serif;background:" + BG + ";border:1px solid " + LINE +
         ";border-radius:18px;padding:14px;",
  list: "display:flex;flex-wrap:wrap;gap:12px;",
  card: "flex:1 1 320px;min-width:0;box-sizing:border-box;background:" + CARD +
        ";border:1px solid " + LINE + ";border-radius:16px;padding:16px;",
  header: "display:flex;justify-content:space-between;gap:14px;align-items:flex-start;margin-bottom:12px;",
  title: "color:" + INK + ";font-size:16px;font-weight:700;letter-spacing:-0.01em;",
  pill: "display:inline-block;background:" + SKY + ";color:" + BLUE +
        ";border-radius:999px;padding:5px 10px;font-size:11px;font-weight:700;white-space:nowrap;",
  passengers: "color:" + INK + ";font-size:13px;line-height:1.45;margin-bottom:12px;",
  meta: "display:flex;flex-wrap:wrap;gap:8px;margin-bottom:12px;",
  metaItem: "background:" + SAND + ";border-radius:10px;padding:7px 9px;min-width:96px;",
  metaLabel: "display:block;color:" + MUTED + ";font-size:10px;font-weight:700;" +
             "text-transform:uppercase;letter-spacing:0.04em;margin-bottom:2px;",
  metaValue: "display:block;color:" + INK + ";font-size:12px;font-weight:600;",
  notes: "color:#344054;background:#fafafa;border:1px solid " + LINE +
         ";border-radius:12px;padding:10px 12px;font-size:13px;line-height:1.45;" +
         "white-space:pre-wrap;margin-bottom:12px;",
  actionRow: "display:block;",
  actionLabel: "display:block;color:" + MUTED + ";font-size:11px;font-weight:700;" +
               "text-transform:uppercase;letter-spacing:0.04em;margin-bottom:6px;",
  select: "width:100%;box-sizing:border-box;padding:11px 12px;font-size:14px;font-weight:600;color:" +
          INK + ";background:" + GREEN + ";border:1px solid #c8d8cd;border-radius:12px;cursor:pointer;",
  empty: "background:" + CARD + ";border:1px dashed " + LINE + ";border-radius:14px;" +
         "padding:22px;text-align:center;color:" + MUTED + ";font-size:14px;"
};

function escapeHtml(value) {
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function buildActionDropdown(item, rowIndex) {
  const uniqueActions = [];
  const seen = {};
  item.actions_array.forEach(action => {
    const id = String(action.actionId || action.id);
    if (seen[id]) return;
    seen[id] = true;
    uniqueActions.push({ id: id, name: action.name });
  });

  const variableName = "customer_action_" + item.pnr + "_" + rowIndex;
  const submitted = String(ZT.getVariableValue(variableName, "")).trim();
  const resolvedName = String(item.customer_action || "").trim();

  function isChosen(option) {
    if (submitted) return option.id === submitted || option.name === submitted;
    return resolvedName && option.name === resolvedName;
  }

  const anyChosen = uniqueActions.some(isChosen);

  // A stored selection that matches nothing on offer is stale (the agent went back
  // and changed the PNR's type after picking). Clear it so node 27 sees a clean
  // blank instead of failing to resolve a value that looks chosen but isn't.
  if (submitted && !anyChosen) {
    ZT.setFormData(variableName, "");
  }

  return `<select name="${escapeHtml(variableName)}" class="zt-data" style="${S.select}">` +
         `<option value=""${anyChosen ? "" : " selected"}>Select action</option>` +
         uniqueActions.map(a =>
           `<option value="${escapeHtml(a.id)}"${isChosen(a) ? " selected" : ""}>${escapeHtml(a.name)}</option>`
         ).join("") +
         `</select>`;
}

function buildMeta(label, value) {
  if (!value) return "";
  return `<div style="${S.metaItem}">` +
         `<span style="${S.metaLabel}">${escapeHtml(label)}</span>` +
         `<strong style="${S.metaValue}">${escapeHtml(value)}</strong>` +
         `</div>`;
}

function buildCustomerActionTable(pnrItems) {
  let html = `<div style="${S.board}"><div style="${S.list}">`;

  if (!pnrItems.length) {
    html += `<div style="${S.empty}">No customer action records found.</div>`;
  } else {
    pnrItems.forEach((item, index) => {
      html += `<div style="${S.card}">` +
                `<div style="${S.header}">` +
                  `<div style="${S.title}">${escapeHtml(item.pnr)}</div>` +
                  (item.category ? `<div style="${S.pill}">${escapeHtml(item.category)}</div>` : "") +
                `</div>` +
                `<div style="${S.passengers}">${item.formatted_passengers || ""}</div>` +
                `<div style="${S.meta}">` +
                  buildMeta("Channel", item.channel) +
                  buildMeta("Type", item.type) +
                `</div>` +
                (item.notes ? `<div style="${S.notes}">${escapeHtml(item.notes)}</div>` : "") +
                `<div style="${S.actionRow}">` +
                  `<div style="${S.actionLabel}">Customer action</div>` +
                  buildActionDropdown(item, index) +
                `</div>` +
              `</div>`;
    });
  }

  html += `</div></div>`;
  return html;
}

let customer_action_table_html = buildCustomerActionTable(customer_action_pnrs);

ZT.setTransformData("customer_action_table_html", customer_action_table_html);

