}

logFlush();
// ===== END EXECUTION LOG BLOCK =====

// UNIFIED TICKET LOOP (v45). One cursor node for child, silent AND grand child
// tickets. The old grandchild body - nodes 36, 37, 38, 68-72, 85 and their three
// status checks - called the SAME connected objects as this one (#20 create,
// #158 get details, #207 update), so it was a verbatim clone of this loop with a
// different target_ticket_id. It is gone; this node walks both levels.
//
// transforms.work_queue (node 27):
//   [ { ticket: { ..., grand_child_tickets: [ ... ] }, errands: [ ... ] }, ... ]
//
// Depth-first walk, two cursors, both FORM data so they survive the transforms TTL:
//   queue_index       which { ticket, errands } entry we are on
//   grandchild_index  -1 = the parent ticket itself, 0..n-1 = that grand child
//
// Order matters and is guaranteed by the walk: a parent is always created and
// resolved before any of its grand children, so the grand child's
// target_ticket_id is already sitting in resolved_ticket_ids_by_queue_index.

let work_queue = transforms.work_queue || [];
let queue_index = parseInt(ZT.getVariableValue("queue_index", 0), 10);
let grandchild_index = parseInt(ZT.getVariableValue("grandchild_index", -1), 10);

// Clamp on entry - every cursor loop in this tree does. See claude.md.
if (queue_index >= work_queue.length) {
  queue_index = 0;
  grandchild_index = -1;
}

const entry = work_queue[queue_index];
const parent_ticket = entry.ticket;
const grand_children = parent_ticket.grand_child_tickets || [];
const is_grand_child = grandchild_index >= 0;
const current_ticket = is_grand_child ? grand_children[grandchild_index] : parent_ticket;

// --- advance the cursor -----------------------------------------------------
function nextPosition() {
  if (!is_grand_child && grand_children.length) return { queue: queue_index, grandchild: 0 };
  if (is_grand_child && grandchild_index + 1 < grand_children.length) {
    return { queue: queue_index, grandchild: grandchild_index + 1 };
  }
  return { queue: queue_index + 1, grandchild: -1 };
}

const next = nextPosition();
const is_more_tickets = next.queue < work_queue.length;

ZT.setFormData("queue_index", is_more_tickets ? next.queue : 0);
ZT.setFormData("grandchild_index", is_more_tickets ? next.grandchild : -1);
ZT.setFormData("is_more_tickets", is_more_tickets);

// The position being processed THIS pass, for the scripts that run after the
// cursor has already moved on (node 65 needs to know which queue entry it just
// resolved a ticket id for).
ZT.setFormData("current_queue_index", queue_index);
ZT.setFormData("current_is_grand_child", is_grand_child);

// --- agent-facing counters (node 84's heading) ------------------------------
let positions = [];
work_queue.forEach((item, qi) => {
  positions.push(qi + "|-1");
  (item.ticket.grand_child_tickets || []).forEach((gc, gi) => positions.push(qi + "|" + gi));
});
ZT.setFormData("ticket_display_index", positions.indexOf(queue_index + "|" + grandchild_index) + 1);
ZT.setFormData("tickets_total", positions.length);

const ticket_kind_label = is_grand_child
  ? "Grand Child Ticket"
  : (current_ticket.kind === "silent" ? "Silent Ticket" : "Child Ticket");
ZT.setFormData("ticket_kind", ticket_kind_label);

// --- Zendesk payload for node 33 (CO #20) -----------------------------------
// Order reference: form data survives a resume, but node 10 (which sets it) only
// runs on a fresh start or Restart, so a deep resume falls through to findorder.
const orderReference =
  ZT.getVariableValue("orderReference", "") ||
  ZT.getVariableValue("custom_field_33772689958162", "") ||
  (actions.findorder && actions.findorder.orderReference) || "";

// A parent ticket hangs off the Zendesk root ticket; a grand child hangs off its
// own parent's resolved ticket id, recorded by node 65 on the parent's pass.
const resolved_ticket_ids = transforms.resolved_ticket_ids_by_queue_index || {};
const target_ticket_id = is_grand_child
  ? resolved_ticket_ids[queue_index]
  : ZT.getVariableValue("zd_ticket_id", "");

// Transform name stays `child_ticket`: CO #20's request body reads
// ${transforms.child_ticket.*} and lives in the admin UI, not in this export.
const child_ticket = {
  subject: current_ticket.title,
  body: "Order Reference: " + (orderReference || "N/A") +
    ", Bucket: " + current_ticket.bucket +
    ", Customer Action: " + current_ticket.customer_action +
    ", Category: " + current_ticket.category +
    ", Type: " + current_ticket.type,
