  target_ticket_id: target_ticket_id
};

ZT.setFormData("orderReference", orderReference);
ZT.setTransformData("current_ticket", current_ticket);
ZT.setTransformData("child_ticket", child_ticket);

// Errand -> parent ticket id, keyed the way node 27/44 key an errand. Only grand
// children have a parent that is itself a side-conversation ticket.
if (is_grand_child) {
  const parent_ticket_ids_by_errand_key = transforms.parent_ticket_ids_by_errand_key || {};
  parent_ticket_ids_by_errand_key[current_ticket.errand_key] = target_ticket_id;
  ZT.setTransformData("parent_ticket_ids_by_errand_key", parent_ticket_ids_by_errand_key);
}

// --- agent card (node 84) ---------------------------------------------------
function buildTicketCardHtml(ticket, ticketFields) {
  function esc(s) {
    if (s === null || s === undefined) return "";
    return String(s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  }

  function humanize(v) {
    if (!v) return "";
    const parts = String(v).split("__");
    return parts[parts.length - 1].replace(/_/g, " ").replace(/\b\w/g, c => c.toUpperCase());
  }

  function row(label, value) {
    if (value === null || value === undefined || value === "") return "";
    return '<div style="margin:6px 0;font-size:13px;">' +
      '<span style="color:#6b7280;font-weight:600;">' + esc(label) + ':</span> ' +
      '<span style="color:#111827;">' + esc(value) + '</span></div>';
  }

  function heading(text) {
    return '<div style="margin-top:14px;margin-bottom:4px;font-weight:700;font-size:12px;' +
      'color:#374151;text-transform:uppercase;letter-spacing:0.03em;">' + esc(text) + '</div>';
  }

  const passengers = ticket.passengers || [];
  const passengersHtml = passengers.length
    ? passengers.map(p => row("First Name", p.passengerFirstName || "") + row("Last Name", p.passengerLastName || ""))
        .join('<div style="border-top:1px solid #f3f4f6;margin:8px 0;"></div>')
    : '<div style="color:#9ca3af;font-size:13px;font-style:italic;">No passenger details available</div>';

  return '<div style="font-family:Arial,Helvetica,sans-serif;max-width:420px;border:1px solid #e5e7eb;' +
    'border-radius:8px;padding:14px 16px;background:#ffffff;">' +
    '<div style="font-size:15px;font-weight:700;color:#111827;margin-bottom:2px;">' +
    esc(ticket.title || ("PNR " + (ticket.pnr || ""))) + '</div>' +
    '<div style="font-size:12px;color:#6b7280;margin-bottom:6px;">' +
    esc(ticket.type) + (ticket.category ? ' - ' + esc(ticket.category) : '') + '</div>' +
    row("Bucket", ticket.bucket) +
    row("PNR", ticket.pnr) +
    row("Customer Action", ticket.customer_action) +
    row("Contact Reason", humanize(ticket.contact_reason)) +
    row("Channel", ticket.channel) +
    heading("Ticket Info") +
    row("Order Reference", ticketFields.order_reference) +
    row("Ticket Contact Reason", humanize(ticketFields.ticket_contact_reason)) +
    row("Conversation ID", ticketFields.conversation_id) +
    row("Conversation Type", humanize(ticketFields.conversation_type)) +
    heading("Passengers") +
    passengersHtml +
    '</div>';
}

ZT.setTransformData("ticket_card_html", buildTicketCardHtml(current_ticket, {
  order_reference: ZT.getVariableValue("custom_field_33772689958162", ""),
  ticket_contact_reason: ZT.getVariableValue("custom_field_29559177650834", ""),
  conversation_id: ZT.getVariableValue("custom_field_31975964556050", ""),
  conversation_type: ZT.getVariableValue("custom_field_31213052370194", "")
}));

logArm("node 33", "Create " + ticket_kind_label, "create_child_ticket", current_ticket.title);

